import java.util.*;

public class Main {
    static Scanner scanner = new Scanner(System.in);

    private static String readLn() {
        return scanner.nextLine();
    }

    private static int readInt() {
        return Integer.parseInt(readLn());
    }

    private static long readLong() {
        return Long.parseLong(readLn());
    }

    private static double readDouble() {
        return Double.parseDouble(readLn());
    }

    private static String[] readStrings() {
        return readLn().split(" ");
    }

    private static int[] readInts() {
        String[] parts = readStrings();
        int[] res = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            res[i] = Integer.parseInt(parts[i]);
        }
        return res;
    }

    private static long[] readLongs() {
        String[] parts = readStrings();
        long[] res = new long[parts.length];
        for (int i = 0; i < parts.length; i++) {
            res[i] = Long.parseLong(parts[i]);
        }
        return res;
    }

    private static double[] readDoubles() {
        String[] parts = readStrings();
        double[] res = new double[parts.length];
        for (int i = 0; i < parts.length; i++) {
            res[i] = Double.parseDouble(parts[i]);
        }
        return res;
    }

    private static void myAssert(boolean x) {
        if (!x) {
            throw new AssertionError();
        }
    }

    public static void main(String[] args) {
        int[] vals = readInts();
        int n = vals[0];
        int t = vals[1];
        int k = vals[2];
        int d = vals[3];

        int tt = t;
        int kk = k;
        while (kk < n) {
            kk += k;
            tt += t;
        }
        if (t + d < tt) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

